<script setup lang="ts" generic="T extends number|[number,number]=number">
import {computed} from 'vue'
import {useHysRootAttrs} from '../../config'
const props=withDefaults(defineProps<{modelValue:T;min?:number;max?:number;step?:number;disabled?:boolean;label?:string;showValue?:boolean;marks?:Record<number,string>;formatTooltip?:(value:number)=>string}>(),{min:0,max:100,step:1,showValue:true})
const emit=defineEmits<{'update:modelValue':[value:T];change:[value:T]}>(),hysRootAttrs=useHysRootAttrs(),range=computed(()=>Array.isArray(props.modelValue)),values=computed<number[]>(()=>Array.isArray(props.modelValue)?props.modelValue:[props.modelValue as number])
const safeStep=computed(()=>Number.isFinite(props.step)&&props.step>0?props.step:1)
const normalize=(value:number)=>Math.max(props.min,Math.min(Math.max(props.min,props.max),Number((props.min+Math.round((value-props.min)/safeStep.value)*safeStep.value).toFixed(10))))
const percent=(value:number)=>Math.max(0,Math.min(100,(value-props.min)/(props.max>props.min?props.max-props.min:1)*100))
function track(event:PointerEvent){if(props.disabled||!range.value)return;const box=(event.currentTarget as HTMLElement).getBoundingClientRect();if(!box.width)return;const next=normalize(props.min+(event.clientX-box.left)/box.width*(props.max-props.min)),pair=[...values.value] as [number,number],index=Math.abs(next-pair[0])<Math.abs(next-pair[1])?0:1;pair[index]=Math.max(index===1?pair[0]:props.min,Math.min(index===0?pair[1]:props.max,next));emit('update:modelValue',pair as T);emit('change',pair as T)}
function value(event:Event,index:number){const next=normalize(Number((event.target as HTMLInputElement).value));if(range.value){const pair=[...values.value] as [number,number];pair[index]=Math.max(index===1?pair[0]:props.min,Math.min(index===0?pair[1]:props.max,next));return pair as T}return next as T}
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-ex-field"><span v-if="showValue">{{label||'数值'}}：{{values.map(v=>formatTooltip?formatTooltip(v):v).join(' ~ ')}}</span><div :class="{'hys-ui-slider-range':range}" @pointerdown.self="track"><div v-if="range" class="hys-ui-slider-selection" :style="{left:percent(values[0])+'%',width:(percent(values[1])-percent(values[0]))+'%'}"/><input v-for="(item,index) in values" :key="index" class="hys-ui-ex-slider" type="range" :aria-label="(label||'数值')+(range?(index===0?'下限':'上限'):'')" :min="min" :max="max" :step="safeStep" :value="item" :disabled="disabled" :aria-valuetext="formatTooltip?.(item)" @input="emit('update:modelValue',value($event,index))" @change="emit('change',value($event,index))"/></div><div v-if="marks" class="hys-ui-slider-marks"><span v-for="(text,key) in marks" :key="key" :style="{left:percent(Number(key))+'%'}">{{text}}</span></div></div></template>
<style scoped>.hys-ui-slider-marks{height:18px;position:relative;font-size:10px;color:var(--hys-ui-muted,var(--hys-ui-theme-muted))}.hys-ui-slider-marks span{position:absolute;transform:translateX(-50%)}.hys-ui-slider-range{position:relative;height:28px;touch-action:none}.hys-ui-slider-range:before{content:'';position:absolute;left:0;right:0;top:12px;height:4px;background:var(--hys-ui-border,var(--hys-ui-theme-border));border-radius:4px;pointer-events:none}.hys-ui-slider-selection{position:absolute;top:12px;height:4px;background:var(--hys-ui-primary,var(--hys-ui-theme-primary));border-radius:4px;pointer-events:none}.hys-ui-slider-range input{position:absolute;inset:0;width:100%;height:28px;margin:0;appearance:none;background:transparent;pointer-events:none}.hys-ui-slider-range input:focus{z-index:2}.hys-ui-slider-range input::-webkit-slider-thumb{appearance:none;width:14px;height:14px;border:2px solid #fff;border-radius:50%;background:var(--hys-ui-primary,var(--hys-ui-theme-primary));box-shadow:0 0 0 1px var(--hys-ui-primary,var(--hys-ui-theme-primary));pointer-events:auto;cursor:grab}.hys-ui-slider-range input::-moz-range-thumb{width:10px;height:10px;border:2px solid #fff;border-radius:50%;background:var(--hys-ui-primary,var(--hys-ui-theme-primary));box-shadow:0 0 0 1px var(--hys-ui-primary,var(--hys-ui-theme-primary));pointer-events:auto;cursor:grab}.hys-ui-slider-range input:disabled::-webkit-slider-thumb{cursor:not-allowed}</style>
